import 'package:flutter/material.dart';import 'package:get/get.dart';import '../../../controllers/auth_controller.dart';
class ForgotPasswordScreen extends GetView<AuthController>{const ForgotPasswordScreen({super.key});@override Widget build(BuildContext context){final email=controller.emailInput;return Scaffold(appBar:AppBar(title:const Text('Reset password')),body:Padding(padding:const EdgeInsets.all(22),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('Forgot your password?',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Enter your email address and we will send a reset link.'),const SizedBox(height:20),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email address')),const SizedBox(height:12),Obx(()=>controller.error.value.isEmpty?const SizedBox.shrink():Text(controller.error.value,style:const TextStyle(color:Colors.red))),Obx(()=>FilledButton(onPressed:controller.loading.value?null:()async{final ok=await controller.forgotPassword(email.text);if(ok)Get.snackbar('Check your email','If the address is eligible, a password reset link has been sent.');},child:controller.loading.value?const CircularProgressIndicator(color:Colors.white):const Text('Send reset link')))])));}}
